1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * Canonical soft-match (possible-duplicate) rule for the owner pipelines, defined once so the
8	 * create and fetch pipelines agree. An owner is a possible duplicate of an existing owner when it
9	 * is not a hard duplicate (their {@link OwnerIdentity identity keys} differ, so the create was not
10	 * rejected with a 409) yet they share the {@link Soundex soundex} of their last name and the same
11	 * postcode.
12	 *
13	 * <p>This is the behaviour change of the single-identity-key design: two owners with the same last
14	 * name and postcode but different telephones now derive different identity keys, so they are
15	 * created rather than rejected, and each is flagged as a soft match of the other.
16	 *
17	 * <p>The match compares the last name by its soundex code and the postcode by its trimmed value. A
18	 * possible duplicate is only possible when the owner itself has a postcode. When several existing
19	 * owners match, the one with the lowest id (the earliest created) is reported for a deterministic
20	 * result.
21	 */
22	final class PossibleDuplicate {
23	
24	    private PossibleDuplicate() {
25	    }
26	
27	    /**
28	     * The id of the existing owner that {@code owner} possibly duplicates, or {@code null} when it
29	     * is not a possible duplicate. The owner itself (matched by id) is never considered its own
30	     * duplicate, an existing owner carrying the identical identity key is a hard duplicate rather
31	     * than a soft match (so it is skipped), and only {@link ActiveOwners active owners} are scanned
32	     * so a soft-deleted owner is never reported as a match.
33	     */
34	    static Integer matchOf(Owner owner, OwnerRepository ownerRepository) {
35	        String postcode = normalizePostcode(owner.getPostcode());
36	        if (postcode == null) {
37	            return null;
38	        }
39	        String soundex = Soundex.encode(owner.getLastName());
40	        String key = OwnerIdentity.of(owner);
41	        Integer match = null;
42	        for (Owner existing : ActiveOwners.list(ownerRepository)) {
43	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
44	                continue;
45	            }
46	            if (!soundex.equals(Soundex.encode(existing.getLastName()))) {
47	                continue;
48	            }
49	            if (!postcode.equals(normalizePostcode(existing.getPostcode()))) {
50	                continue;
51	            }
52	            if (key.equals(OwnerIdentity.of(existing))) {
53	                // Identical identity key: a hard duplicate, not a soft match.
54	                continue;
55	            }
56	            if (existing.getId() != null && (match == null || existing.getId() < match)) {
57	                match = existing.getId();
58	            }
59	        }
60	        return match;
61	    }
62	
63	    /** Trimmed postcode, or {@code null} when absent/blank (no postcode means no soft match). */
64	    private static String normalizePostcode(String value) {
65	        if (value == null || value.isBlank()) {
66	            return null;
67	        }
68	        return value.trim();
69	    }
70	}
