28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "address_line1")
44	    private String addressLine1;
45	
46	    @Column(name = "address_line2")
47	    private String addressLine2;
48	
49	    @Column(name = "city")
50	    @NotEmpty
51	    private String city;
52	
53	    @Column(name = "telephone")
54	    @NotEmpty
55	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
56	    private String telephone;
57	
58	    @Column(name = "email")
59	    private String email;
60	
61	    @Column(name = "title")
62	    private String title;
63	
64	    @Column(name = "registration_date")
65	    private LocalDate registrationDate;
66	
67	    @Column(name = "birth_date")
68	    private LocalDate birthDate;
69	
70	    @Column(name = "member_id")
71	    private String memberId;
72	
73	    @Column(name = "household_id")
74	    private String householdId;
75	
76	    @Column(name = "namesake_count")
77	    private Integer namesakeCount;
78	
79	    @Column(name = "postcode")
80	    private String postcode;
81	
82	    @Column(name = "deleted", nullable = false)
83	    private boolean deleted;
84	
85	    @Transient
86	    private Integer householdSize;
87	
88	    @Transient
89	    private Integer membershipLevelCap;
90	
91	    @Transient
92	    private boolean bulkSignupWarning;
93	
94	    @Transient
95	    private boolean capacityWarning;
96	
97	    @Transient
98	    private boolean possibleDuplicate;
99	
100	    @Transient
101	    private Integer possibleDuplicateOf;
102	
103	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
104	    private Set<Pet> pets;
105	
106	    public String getAddress() {
107	        return this.address;
108	    }
109	
110	    public void setAddress(String address) {
111	        this.address = address;
112	    }
113	
114	    public String getAddressLine1() {
115	        return this.addressLine1;
116	    }
117	
118	    public void setAddressLine1(String addressLine1) {
119	        this.addressLine1 = addressLine1;
120	    }
121	
122	    public String getAddressLine2() {
123	        return this.addressLine2;
124	    }
125	
126	    public void setAddressLine2(String addressLine2) {
127	        this.addressLine2 = addressLine2;
128	    }
129	
130	    public String getCity() {
131	        return this.city;
132	    }
133	
134	    public void setCity(String city) {
135	        this.city = city;
136	    }
137	
138	    public String getTelephone() {
139	        return this.telephone;
140	    }
141	
142	    public void setTelephone(String telephone) {
143	        this.telephone = telephone;
144	    }
145	
146	    public String getEmail() {
147	        return this.email;
148	    }
149	
150	    public void setEmail(String email) {
151	        this.email = email;
152	    }
153	
154	    public String getTitle() {
155	        return this.title;
156	    }
157	
158	    public void setTitle(String title) {
159	        this.title = title;
160	    }
161	
162	    public LocalDate getRegistrationDate() {
163	        return this.registrationDate;
164	    }
165	
166	    public void setRegistrationDate(LocalDate registrationDate) {
167	        this.registrationDate = registrationDate;
168	    }
169	
170	    public LocalDate getBirthDate() {
171	        return this.birthDate;
172	    }
173	
174	    public void setBirthDate(LocalDate birthDate) {
175	        this.birthDate = birthDate;
176	    }
177	
178	    public String getMemberId() {
179	        return this.memberId;
180	    }
181	
182	    public void setMemberId(String memberId) {
183	        this.memberId = memberId;
184	    }
185	
186	    public String getHouseholdId() {
187	        return this.householdId;
188	    }
189	
190	    public void setHouseholdId(String householdId) {
191	        this.householdId = householdId;
192	    }
193	
194	    /**
195	     * The number of owners in this owner's household (owners sharing its householdId, counting
196	     * this owner). Not a persisted column — populated by the owner pipelines (create and read)
197	     * that have repository access, and consumed only by {@link #getMembershipPoints()}. {@code
198	     * null} when it has not been resolved, which the points rule treats as a single-member
199	     * household.
200	     */
201	    @Transient
202	    public Integer getHouseholdSize() {
203	        return this.householdSize;
204	    }
205	
206	    public void setHouseholdSize(Integer householdSize) {
207	        this.householdSize = householdSize;
208	    }
209	
210	    /**
211	     * The ceiling applied to this owner's {@link #getMembershipLevel() membershipLevel}: the new
212	     * owner's level cannot exceed one above the maximum level among the other members of its
213	     * household. Not a persisted column — populated by the create pipeline, which alone has the
214	     * repository access to read the household's members. {@code null} when no cap applies (the
215	     * owner has no existing household member), leaving the level uncapped.
216	     */
217	    @Transient
218	    public Integer getMembershipLevelCap() {
219	        return this.membershipLevelCap;
220	    }
221	
222	    public void setMembershipLevelCap(Integer membershipLevelCap) {
223	        this.membershipLevelCap = membershipLevelCap;
224	    }
225	
226	    public Integer getNamesakeCount() {
227	        return this.namesakeCount;
228	    }
229	
230	    public void setNamesakeCount(Integer namesakeCount) {
231	        this.namesakeCount = namesakeCount;
232	    }
233	
234	    public String getPostcode() {
235	        return this.postcode;
236	    }
237	
238	    public void setPostcode(String postcode) {
239	        this.postcode = postcode;
240	    }
241	
242	    /**
243	     * Whether this owner has been soft-deleted. A soft-delete ({@code DELETE /api/owners/{id}})
244	     * flags the owner deleted and retains the row rather than removing it, so the owner is still
245	     * returned by a fetch; the create pipeline's duplicate and identity checks ignore owners
246	     * flagged deleted. A newly created owner is not deleted.
247	     */
248	    public boolean isDeleted() {
249	        return this.deleted;
250	    }
251	
252	    public void setDeleted(boolean deleted) {
253	        this.deleted = deleted;
254	    }
255	
256	    /**
257	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
258	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
259	     */
260	    @Transient
261	    public String getDisplayName() {
262	        return this.getLastName() + ", " + this.getFirstName();
263	    }
264	
265	    /**
266	     * The owner's initials: the upper-cased first letters of firstName and lastName,
267	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
268	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
269	     */
270	    @Transient
271	    public String getInitials() {
272	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
273	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
274	    }
275	
276	    /**
277	     * The owner's salutation: the {@link #getTitle() title} and {@link #getLastName() lastName}
278	     * separated by a single space (e.g. {@code 'DR Who'}), or just the last name when no title is
279	     * supplied. Not persisted — derived from {@link #getTitle()} and {@link #getLastName()}.
280	     */
281	    @Transient
282	    public String getSalutation() {
283	        if (this.title == null || this.title.isBlank()) {
284	            return this.getLastName();
285	        }
286	        return this.title + " " + this.getLastName();
287	    }
288	
289	    /**
290	     * The owner's {@link #getTelephone() telephone} formatted for humans: the stored E.164
291	     * value rewritten as the country code, a space, then the national digits grouped in threes
292	     * separated by spaces (e.g. {@code '+61 412 345 678'}). The known country codes are
293	     * {@code '+61'} (Australia) and {@code '+1'} (NANP); any other E.164 value is split with a
294	     * two-digit country code. {@code null} when no telephone is set or the value is not in E.164
295	     * form. The raw {@link #getTelephone() telephone} is left in E.164 form. Not persisted —
296	     * derived from {@link #getTelephone()}.
297	     */
298	    @Transient
299	    public String getTelephoneDisplay() {
300	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
301	            return null;
302	        }
303	        String digits = this.telephone.substring(1);
304	        int countryCodeLength = digits.startsWith("1") && !digits.startsWith("61") ? 1 : 2;
305	        if (digits.length() <= countryCodeLength) {
306	            return this.telephone;
307	        }
308	        String countryCode = digits.substring(0, countryCodeLength);
309	        String national = digits.substring(countryCodeLength);
310	        StringBuilder grouped = new StringBuilder();
311	        for (int i = 0; i < national.length(); i++) {
312	            if (i > 0 && i % 3 == 0) {
313	                grouped.append(' ');
314	            }
315	            grouped.append(national.charAt(i));
316	        }
317	        return "+" + countryCode + " " + grouped;
318	    }
319	
320	    /**
321	     * The calendar year in which {@code date}'s fiscal year starts. The fiscal year starts on
322	     * 1 July, so a date in July–December belongs to the fiscal year starting that calendar year,
323	     * while a date in January–June belongs to the fiscal year that started the previous calendar
324	     * year.
325	     */
326	    private static int fiscalYearStart(LocalDate date) {
327	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
328	    }
329	
330	    /**
331	     * The 2-digit fiscal-year segment ({@code 'YY'}) for {@code date}: the last two digits of the
332	     * calendar year in which the fiscal year starts (the fiscal year starts on 1 July), zero-padded
333	     * (e.g. a date in October 2026 yields {@code '26'}). The single authority for the FY segment of
334	     * the owner's {@link #getMemberId() memberId}, reused by the create pipeline so the memberId and
335	     * the derived {@link #getFiscalYear() fiscalYear} agree on it.
336	     */
337	    public static String fiscalYearSegment(LocalDate date) {
338	        return String.format("%02d", fiscalYearStart(date) % 100);
339	    }
340	
341	    /** The length of the fixed {@code <FY><HASH8><CHK>} tail of a {@link #getMemberId() memberId}
342	     * core: 2 (FY) + 8 (HASH8) + 1 (CHK). The REGION prefix is whatever precedes this tail. */
343	    private static final int MEMBER_ID_TAIL = 11;
344	
345	    /**
346	     * The owner's memberId with any {@code '-<n>'} collision suffix removed, or {@code null} when no
347	     * memberId is set or the value is too short to carry the fixed {@code <FY><HASH8><CHK>} tail.
348	     * The core is {@code <REGION><FY><HASH8><CHK>}; collision handling appends {@code '-<n>'} and
349	     * REGION/FY/HASH8/CHK contain no {@code '-'}, so the segments can be read off the core by length.
350	     */
351	    private String memberIdCore() {
352	        if (this.memberId == null) {
353	            return null;
354	        }
355	        int dash = this.memberId.indexOf('-');
356	        String core = dash < 0 ? this.memberId : this.memberId.substring(0, dash);
357	        return core.length() < MEMBER_ID_TAIL ? null : core;
358	    }
359	
360	    /**
361	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the 2-digit fiscal-year
362	     * segment of the owner's {@link #getMemberId() memberId} (e.g. a memberId {@code 'NSW261A2B3C4D7'}
363	     * yields {@code 'FY26'}). The memberId's FY segment is derived from the business-day-adjusted
364	     * {@link #getRegistrationDate() registrationDate}. {@code null} when no memberId is set. Not
365	     * persisted — derived from {@link #getMemberId()}.
366	     */
367	    @Transient
368	    public String getFiscalYear() {
369	        String core = memberIdCore();
370	        if (core == null) {
371	            return null;
372	        }
373	        return "FY" + core.substring(core.length() - MEMBER_ID_TAIL, core.length() - MEMBER_ID_TAIL + 2);
374	    }
375	
376	    /**
377	     * The owner's membership points. Starts at {@code 0}; adds {@code 2} when an
378	     * {@link #getEmail() email} is present; adds {@code 1} when {@link #getNamesakeCount()
379	     * namesakeCount} is {@code 0}; adds {@code 2} for a household of {@code 3} or more members
380	     * ({@link #getHouseholdSize() householdSize}); adds {@code 3} for a tenure of one or more
381	     * elapsed fiscal years since the {@link #getRegistrationDate() registration date}'s fiscal
382	     * year (the fiscal year starts on 1 July). Not persisted — derived from {@link #getEmail()},
383	     * {@link #getNamesakeCount()}, {@link #getHouseholdSize()} and {@link #getRegistrationDate()}.
384	     */
385	    @Transient
386	    public int getMembershipPoints() {
387	        int points = 0;
388	        boolean hasEmail = this.email != null && !this.email.isBlank();
389	        if (hasEmail) {
390	            points += 2;
391	        }
392	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
393	        if (uniqueName) {
394	            points += 1;
395	        }
396	        if (this.householdSize != null && this.householdSize >= 3) {
397	            points += 2;
398	        }
399	        if (this.registrationDate != null
400	                && fiscalYearStart(LocalDate.now()) - fiscalYearStart(this.registrationDate) >= 1) {
401	            points += 3;
402	        }
403	        return points;
404	    }
405	
406	    /**
407	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()
408	     * membershipPoints}: {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
409	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more, then capped at
410	     * {@link #getMembershipLevelCap() membershipLevelCap} when one applies (a new owner's level
411	     * cannot exceed one above the maximum level among its existing household members). Not
412	     * persisted — derived from {@link #getMembershipPoints()} and {@link #getMembershipLevelCap()}.
413	     */
414	    @Transient
415	    public int getMembershipLevel() {
416	        int points = getMembershipPoints();
417	        int level;
418	        if (points >= 6) {
419	            level = 4;
420	        }
421	        else if (points >= 4) {
422	            level = 3;
423	        }
424	        else if (points >= 2) {
425	            level = 2;
426	        }
427	        else {
428	            level = 1;
429	        }
430	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
431	            return this.membershipLevelCap;
432	        }
433	        return level;
434	    }
435	
436	    /**
437	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
438	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. TIER is
439	     * {@code 'PREMIUM'} when {@link #getMembershipLevel() membershipLevel} is 3 or more, otherwise
440	     * {@code 'STANDARD'}. AREA is {@code 'METRO'} when the {@link #getLocality() locality} is a known
441	     * region (NSW, VIC or QLD), otherwise {@code 'REGIONAL'}. Not persisted — derived from
442	     * {@link #getMembershipLevel()} and {@link #getLocality()}.
443	     */
444	    @Transient
445	    public String getOwnerSegment() {
446	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
447	        String area = isKnownRegion(getLocality()) ? "METRO" : "REGIONAL";
448	        return tier + "_" + area;
449	    }
450	
451	    /**
452	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
453	     */
454	    private static final Map<String, String> CITY_REGION = Map.of(
455	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
456	
457	    /**
458	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
459	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
460	     */
461	    private static final Map<String, int[]> REGION_RANGE = Map.of(
462	        "NSW", new int[] {2000, 2099},
463	        "VIC", new int[] {3000, 3099},
464	        "QLD", new int[] {4000, 4099});
465	
466	    /**
467	     * Fixed region -> IANA timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
468	     * QLD->Australia/Brisbane), the single authority for {@link #getTimezone()}.
469	     */
470	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
471	        "NSW", "Australia/Sydney",
472	        "VIC", "Australia/Melbourne",
473	        "QLD", "Australia/Brisbane");
474	
475	    /**
476	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
477	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
478	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
479	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
480	     * the owner's {@link #getMemberId() memberId}, so the create pipeline and
481	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
482	     * by the owner pipelines (e.g. postcode validation) rather than copied.
483	     */
484	    public static String regionFor(String postcode, String city) {
485	        String region = regionForPostcode(postcode);
486	        if (region != null) {
487	            return region;
488	        }
489	        String cityRegion = regionForCity(city);
490	        return cityRegion != null ? cityRegion : "UNKNOWN";
491	    }
492	
493	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
494	     * Brisbane->QLD), or {@code null} when the city has no known region. */
495	    public static String regionForCity(String city) {
496	        return city == null ? null : CITY_REGION.get(city);
497	    }
498	
499	    /** Whether {@code region} is one of the known regions (NSW, VIC or QLD); {@code 'UNKNOWN'}
500	     * and any other value are not. Backed by {@link #REGION_RANGE}, the primary source for the
501	     * region set. */
502	    public static boolean isKnownRegion(String region) {
503	        return REGION_RANGE.containsKey(region);
504	    }
505	
506	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
507	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
508	     * range. */
509	    public static String regionForPostcode(String postcode) {
510	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
511	            return null;
512	        }
513	        int value = Integer.parseInt(postcode);
514	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
515	            int[] range = entry.getValue();
516	            if (value >= range[0] && value <= range[1]) {
517	                return entry.getKey();
518	            }
519	        }
520	        return null;
521	    }
522	
523	    /**
524	     * The owner's locality: the REGION prefix of the owner's {@link #getMemberId() memberId}
525	     * (everything before the fixed {@code <FY><HASH8><CHK>} tail), which the create pipeline derives
526	     * from the postcode-and-city region. {@code 'UNKNOWN'} when no memberId is set. Not persisted —
527	     * derived from {@link #getMemberId()}.
528	     */
529	    @Transient
530	    public String getLocality() {
531	        String core = memberIdCore();
532	        if (core == null) {
533	            return "UNKNOWN";
534	        }
535	        String region = core.substring(0, core.length() - MEMBER_ID_TAIL);
536	        return region.isEmpty() ? "UNKNOWN" : region;
537	    }
538	
539	    /**
540	     * The owner's timezone: the IANA name for the owner's {@link #getLocality() locality}/region
541	     * from the fixed region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
542	     * QLD->Australia/Brisbane), or {@code null} when the region has no mapped timezone. Not
543	     * persisted — derived from {@link #getLocality()}.
544	     */
545	    @Transient
546	    public String getTimezone() {
547	        return REGION_TIMEZONE.get(getLocality());
548	    }
549	
550	    /**
551	     * Whether more than 80 owners had already been created today when this response was
552	     * built. Not persisted — populated for the response by the create and fetch pipelines
553	     * and defaults to {@code false} so every owner serialization carries the flag.
554	     */
555	    @Transient
556	    public boolean isBulkSignupWarning() {
557	        return this.bulkSignupWarning;
558	    }
559	
560	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
561	        this.bulkSignupWarning = bulkSignupWarning;
562	    }
563	
564	    /**
565	     * Whether this owner's city already held between 40 and 49 owners when this response was
566	     * built, approaching the hard capacity limit of 50 (compared case-insensitively). Not
567	     * persisted — populated for the response by the create and fetch pipelines and defaults to
568	     * {@code false} so every owner serialization carries the flag.
569	     */
570	    @Transient
571	    public boolean isCapacityWarning() {
572	        return this.capacityWarning;
573	    }
574	
575	    public void setCapacityWarning(boolean capacityWarning) {
576	        this.capacityWarning = capacityWarning;
577	    }
578	
579	    /**
580	     * Whether this owner is a possible (soft) duplicate: not a hard duplicate, but shares an
581	     * existing owner's last name and postcode with a different telephone. Not persisted —
582	     * populated for the response by the create and fetch pipelines and defaults to
583	     * {@code false} so every owner serialization carries the flag.
584	     */
585	    @Transient
586	    public boolean isPossibleDuplicate() {
587	        return this.possibleDuplicate;
588	    }
589	
590	    public void setPossibleDuplicate(boolean possibleDuplicate) {
591	        this.possibleDuplicate = possibleDuplicate;
592	    }
593	
594	    /**
595	     * The id of the existing owner this owner possibly duplicates (shared last name and
596	     * postcode, different telephone), or {@code null} when it is not a possible duplicate.
597	     * Not persisted — populated for the response alongside {@link #isPossibleDuplicate()}.
598	     */
599	    @Transient
600	    public Integer getPossibleDuplicateOf() {
601	        return this.possibleDuplicateOf;
602	    }
603	
604	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
605	        this.possibleDuplicateOf = possibleDuplicateOf;
606	    }
607	
608	    /**
609	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
610	     * is present, otherwise {@code 'PHONE'}.
611	     * Not persisted — derived from {@link #getEmail()}.
612	     */
613	    @Transient
614	    public String getContactPreference() {
615	        boolean hasEmail = this.email != null && !this.email.isBlank();
616	        return hasEmail ? "EMAIL" : "PHONE";
617	    }
618	
619	    /**
620	     * The owner's age band as of the {@link #getRegistrationDate() registrationDate}, derived
621	     * from {@link #getBirthDate() birthDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} for
622	     * 18 to 64 inclusive, {@code 'SENIOR'} for 65 and over. {@code null} when no birthDate is
623	     * supplied. Not persisted — derived from {@link #getBirthDate()} and
624	     * {@link #getRegistrationDate()}.
625	     */
626	    @Transient
627	    public String getAgeBand() {
628	        if (this.birthDate == null || this.registrationDate == null) {
629	            return null;
630	        }
631	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
632	        if (age < 18) {
633	            return "MINOR";
634	        }
635	        return age < 65 ? "ADULT" : "SENIOR";
636	    }
637	
638	    protected Set<Pet> getPetsInternal() {
639	        if (this.pets == null) {
640	            this.pets = new HashSet<>();
641	        }
642	        return this.pets;
643	    }
644	
645	    protected void setPetsInternal(Set<Pet> pets) {
646	        this.pets = pets;
647	    }
648	
649	    public List<Pet> getPets() {
650	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
651	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
652	        return Collections.unmodifiableList(sortedPets);
653	    }
654	
655	    public void setPets(List<Pet> pets) {
656	        this.pets = new HashSet<>(pets);
657	    }
658	
659	    public void addPet(Pet pet) {
660	        getPetsInternal().add(pet);
661	        pet.setOwner(this);
662	    }
663	
664	    /**
665	     * Return the Pet with the given name, or null if none found for this Owner.
666	     *
667	     * @param name to test
668	     * @return true if pet name is already in use
669	     */
670	    public Pet getPet(String name) {
671	        return getPet(name, false);
672	    }
673	
674	    /**
675	     * Return the Pet with the given name, or null if none found for this Owner.
676	     *
677	     * @param name to test
678	     * @return true if pet name is already in use
679	     */
680	    public Pet getPet(String name, boolean ignoreNew) {
681	        name = name.toLowerCase();
682	        for (Pet pet : getPetsInternal()) {
683	            if (!ignoreNew || !pet.isNew()) {
684	                String compName = pet.getName();
685	                compName = compName.toLowerCase();
686	                if (compName.equals(name)) {
687	                    return pet;
688	                }
689	            }
690	        }
691	        return null;
692	    }
693	
694	    public Pet getPet(Integer petId) {
695	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
696	    }
697	
698	    @Override
699	    public String toString() {
700	        return new ToStringCreator(this)
701	
702	            .append("id", this.getId())
703	            .append("new", this.isNew())
704	            .append("lastName", this.getLastName())
705	            .append("firstName", this.getFirstName())
706	            .append("address", this.address)
707	            .append("city", this.city)
708	            .append("telephone", this.telephone)
709	            .toString();
710	    }
711	}
